(() => {
 const M=CREDIT_MATH,sum=M.sum,clamp=M.clamp,m=x=>(x<0?'−':'')+'£'+Math.abs(x).toFixed(3)+'m',p=x=>(100*x).toFixed(2)+'%',a=(id,label,min,max,step,value,unit='£m')=>({id,label,min,max,step,value,unit}),sel=(id,label,options,value)=>({id,label,options,value}),yes=(id,label,value='no')=>sel(id,label,[['no','No'],['yes','Yes']],value);
 const refs={ifrs:['https://www.ifrs.org/issued-standards/list-of-standards/ifrs-9-financial-instruments/','IFRS 9 · official standard and project resources'],ecl:['https://www.bis.org/committees/bcbs/basel-consolidated-guidelines/module/pap/20','Basel · credit risk and ECL guidance'],model:['https://www.bankofengland.co.uk/prudential-regulation/publication/2023/may/model-risk-management-principles-for-banks-ss','PRA SS1/23 · current April 2026 model-risk principles'],capital:['https://www.bis.org/committees/bcbs/basel-framework/standard/cre','Basel CRE · credit risk framework'],poci:['https://www.ifrs.org/content/dam/ifrs/meetings/2024/april/iasb/ap27b-purchased-or-originated-credit-impaired-assets.pdf','IASB 2024 review · POCI treatment'],matrix:['https://www.ifrs.org/content/dam/ifrs/meetings/2024/may/iasb/ap27c-feedback-analysis-other-matters.pdf','IASB 2024 review · simplified approach'],scenario:['https://www.ifrs.org/content/dam/ifrs/groups/itg/itg-meeting-summaries/itg-meeting-summary-december-2015.pdf','IFRS implementation group · forward-looking scenarios']};
 const bars=(labels,values)=>labels.map((label,i)=>({label,value:values[i],color:values[i]<0?'#b57e3e':['#285e46','#779db0','#93b77b','#b57e3e'][i%4]})),out=(stats,labels,values,rows,explanation,note='')=>({stats,bars:bars(labels,values),headers:['Quantity','Value','Interpretation'],rows,explanation,note});
 const line=(name,data,color='#285e46')=>({name,data,color});
 window.CREDIT_LESSONS=[];
 function add(x){CREDIT_LESSONS.push({stage:'01 · Understand the exposure',simpleTitle:'Build the intuition',key:'Synthetic educational assumptions. PD and LGD are displayed as percentages; currency values are £m. No example certifies accounting or regulatory compliance.',notes:[],sources:[refs.ecl,refs.capital],...x});}
 window.CREDIT_UI={M,sum,clamp,m,p,a,sel,yes,refs,bars,out,line,add};
 add({id:'portfolio',name:'Portfolio loss explorer',title:'Different borrowers. Different paths to loss.',intro:'Choose a portfolio, set drawn and undrawn balances, and compare one-year expected loss with a discounted lifetime loss profile.',chart:'Annual discounted expected loss contributions (£m)',inputs:[sel('type','Portfolio archetype',Object.entries(M.profiles).map(([k,v])=>[k,v.name]),'mortgage'),a('drawn','Drawn balance',0,500,10,100),a('undrawn','Undrawn commitment',0,200,5,20),a('pdScale','PD multiplier',.5,3,.25,1,'×'),a('lgdScale','LGD multiplier',.5,2,.1,1,'×'),a('eir','Effective interest rate',0,15,.5,5,'%')],challenge:'Switch from mortgages to cards without changing the drawn balance. What changes besides PD?',formula:'EAD = drawn + behavioural CCF × undrawn\nEL1y = PD1y × LGD × EAD\nLifetime loss proxy = Σ survival × conditional PD × LGD × future EAD × discount factor',simple:'Borrowers can fail in different ways, and contracts determine how much is exposed and recovered. A mortgage amortises and has collateral; a card can be drawn further just before default. A common formula needs different inputs for each portfolio.',scope:'Seven synthetic profiles; all preset PDs, LGDs, CCFs and lives are teaching assumptions, not market estimates or regulatory factors. Performing exposures only. Lifetime projection uses annual conditional PD, annual end-period loss timing and straight-line balance runoff where selected. This is not an automatic IFRS 9 allowance: staging, scenarios and scope are taught separately.',compute(s){const f=M.profiles[s.type],ead=s.drawn+f.ccf/100*s.undrawn,pd=clamp(f.pd/100*s.pdScale),lgd=clamp(f.lgd/100*s.lgdScale),r=M.ecl({ead,pd,lgd,years:f.years,amort:f.amort,eir:s.eir/100});return {stats:[['EAD',m(ead)],['Undiscounted 1y EL',m(ead*pd*lgd)],['Lifetime loss proxy',m(r.life)]],bars:bars(r.rows.map(x=>'Year '+x.t),r.rows.map(x=>x.loss)),headers:['Year','Conditional PD','Marginal PD','EAD','Discounted loss'],rows:r.rows.map(x=>[x.t,p(x.q),p(x.marginal),m(x.ead),m(x.loss)]),explanation:`${f.name}: PD ${p(pd)}, LGD ${p(lgd)}, assumed CCF ${f.ccf}%, model life ${f.years} years. The main candidate drivers are ${f.drivers}.`,note:'The undiscounted one-year EL and discounted lifetime proxy answer different questions.'};}});
 add({id:'pd',name:'PD and survival curves',title:'A five-year PD is not five times a one-year PD.',intro:'Separate conditional annual default probability, marginal default probability and cumulative default probability.',chart:'Cumulative default probability and survival (%)',inputs:[a('pd','Initial annual conditional PD',0,30,.5,3,'%'),a('trend','Annual log-PD trend',-.4,.4,.05,.1,'per year'),a('years','Horizon',1,15,1,5,'years')],challenge:'Keep annual PD fixed. Why does the marginal default probability decline?',formula:'Marginal PD(t)=survival(t−1) × conditional PD(t)\nSurvival(t)=Π[1−conditional PD(i)]',simple:'Only borrowers still performing can default for the first time. Conditional PD describes that remaining population; marginal PD counts defaults from the original population during one interval.',scope:'One absorbing default state, no cures or prepayment. Trend multiplies conditional PD exponentially and probabilities are capped at 100%. These are synthetic term structures; censoring and cohort estimation are covered in the vintage lesson.',compute(s){const r=M.ecl({pd:s.pd/100,trend:s.trend,years:s.years});return {stats:[['Cumulative PD',p(r.cumulative)],['Survival',p(1-r.cumulative)],['Sum of marginal PDs',p(sum(r.rows.map(x=>x.marginal)))]],series:[line('Cumulative PD',[[0,0],...r.rows.map(x=>[x.t,100*x.cumulative])]),line('Survival',[[0,100],...r.rows.map(x=>[x.t,100*(1-x.cumulative)])],'#779db0')],xlabel:'Year',headers:['Year','Conditional PD','Marginal PD','Cumulative PD'],rows:r.rows.map(x=>[x.t,p(x.q),p(x.marginal),p(x.cumulative)]),explanation:'Survival and cumulative default sum to 100%. Annual conditional probabilities must be survival-weighted before they are added.'};}});
 add({id:'lgd',name:'Recoveries and LGD',title:'Recovering the money late can still leave a loss.',intro:'Discount expected recoveries and workout costs back to default, then calculate an economic loss severity.',chart:'From exposure to recovery value (£m)',inputs:[a('ead','Exposure at default',1,200,1,100),a('recovery','Gross recovery fraction',0,100,5,70,'%'),a('cost','Costs as fraction of EAD',0,30,1,5,'%'),a('lag','Recovery delay',0,7,.5,2,'years'),a('rate','Discount rate assumption',0,20,.5,5,'%')],challenge:'Keep the recovered cash amount fixed but delay receipt. Does LGD stay unchanged?',formula:'PV recovery net of costs = EAD × (recovery% − cost%) / (1+r)^delay\nLGD = 1 − PV recovery / EAD',simple:'A recovery is valuable when it can be used. Delay and collection costs reduce that value even when the borrower ultimately returns a large amount of principal.',scope:'A single recovery and cost payment at the same future date. LGD can exceed 100% if costs exceed recoveries. Chosen discount rate is illustrative; accounting EIR conventions and prudential economic-loss discounting are not interchangeable. No recovery uncertainty or collateral cap in this isolated experiment.',compute(s){const net=s.ead*(s.recovery-s.cost)/100/(1+s.rate/100)**s.lag,loss=s.ead-net;return out([['Net recovery PV',m(net)],['Economic loss',m(loss)],['LGD',p(loss/s.ead)]],['Default EAD','Recovery PV','Loss'],[s.ead,net,loss],[['Gross recovery cash',m(s.ead*s.recovery/100),'Paid at selected delay'],['Costs',m(s.ead*s.cost/100),'Same timing assumption'],['Loss fraction',p(loss/s.ead),'Can exceed 100% with net costs']],`Discounted recovery is ${m(net)} and economic LGD is ${p(loss/s.ead)}. Cash recovery percentage alone is not the same as loss severity.`);}});
 add({id:'ead',name:'EAD and credit conversion',title:'Exposure can grow before a borrower defaults.',intro:'Convert part of an undrawn commitment into expected additional exposure and compare it with the current balance.',chart:'Drawn balance, future drawdown and EAD (£m)',inputs:[a('drawn','Drawn exposure',0,200,5,60),a('undrawn','Undrawn limit',0,200,5,40),a('ccf','Behavioural CCF',0,100,5,60,'%'),a('pd','One-year PD',0,30,.5,5,'%'),a('lgd','LGD',0,100,5,60,'%')],challenge:'Keep the total credit limit fixed and move exposure from undrawn to drawn. What changes?',formula:'EAD=drawn+CCF×undrawn; EL=PD×LGD×EAD',simple:'A struggling customer may use an available line before losing access. Exposure modelling needs the amount available and the expected draw behaviour, not just today’s outstanding amount.',scope:'Behavioural CCF is an adjustable teaching estimate, not a prescribed Basel CCF. No interest accrual, over-limit drawings, cancellations or settlement netting. IFRS 9 and prudential exposure definitions must be matched to their purpose.',compute(s){const add=s.undrawn*s.ccf/100,ead=s.drawn+add;return out([['EAD',m(ead)],['Expected additional draw',m(add)],['One-year EL',m(ead*s.pd*s.lgd/10000)]],['Drawn','Additional draw','EAD'],[s.drawn,add,ead],[['Undrawn line',m(s.undrawn),'Not all necessarily drawn'],['CCF',s.ccf+'%','Behavioural assumption']],`The line contributes ${m(add)} beyond today’s balance. A zero drawn balance can therefore still carry credit risk.`);}});
 add({id:'dependence',name:'Default dependence and tail loss',stage:'02 · Portfolio behaviour',title:'Diversification weakens when defaults arrive together.',intro:'Build an equal-sized loan pool and introduce a shared good/bad regime while keeping each loan’s average PD unchanged.',chart:'Exact portfolio default-count distribution (%)',inputs:[a('n','Number of equal loans',10,200,10,100,'loans'),a('ead','Total portfolio EAD',10,500,10,100),a('pd','Average annual PD',.5,20,.5,3,'%'),a('lgd','Fixed LGD',10,100,5,50,'%'),a('dep','Shared-regime dependence',0,1,.05,.5,'strength'),a('confidence','Tail confidence',95,99.9,.1,99,'%')],challenge:'Increase dependence. Why can expected loss stay fixed while the tail changes?',formula:'P(K=k)=95%×Binomial(n,p_good)+5%×Binomial(n,p_bad)\nWeighted conditional PDs equal the selected average PD\nES averages exactly the worst (1−confidence) loss mass',simple:'An average loss says how much is lost across many possible worlds. Dependence changes which worlds carry those losses: more defaults occur together in the bad state, making the tail heavier.',scope:'Exact two-regime binomial mixture with 5% bad-state probability; loans are independent conditional on the regime, equally sized, fixed LGD, one-year horizon. Dependence slider is not an asset-correlation parameter. Reported default correlation is derived from conditional PD variance. No migration or stochastic recoveries. VaR can move in steps; it need not increase monotonically at every confidence level.',compute(s){const r=M.distribution(s.n,s.pd/100,s.dep,s.ead,s.lgd/100,s.confidence/100);return {stats:[['Expected loss',m(r.mean)],['Loss VaR',m(r.var)],['Tail ES',m(r.es)]],series:[line('Default-count probability',r.mass.map((v,k)=>[k,100*v]))],xlabel:'Number of defaults',headers:['Quantity','Value','Meaning'],rows:[['Good-state PD',p(r.good),'95% regime weight'],['Bad-state PD',p(r.bad),'5% regime weight'],['Default correlation',p(r.corr),'Derived, not the input slider'],['Loss standard deviation',m(r.sd),'Unexpected-loss dispersion'],['VaR minus EL',m(r.var-r.mean),'Economic-capital proxy, not regulatory capital']],explanation:`Average PD stays ${s.pd}%, so EL remains ${m(r.mean)}. Dependence concentrates loss into shared bad states. Default correlation is ${p(r.corr)}.`};}});
 add({id:'concentration',name:'Single-name and sector concentration',stage:'02 · Portfolio behaviour',title:'One large loan can dominate a diversified-looking book.',intro:'Allocate a fixed portfolio between one large borrower and an equally divided remainder.',chart:'Exposure allocation and standalone expected losses (£m)',inputs:[a('ead','Total EAD',10,500,10,100),a('share','Largest borrower share',0,90,5,30,'%'),a('others','Other equal borrowers',1,100,1,20,'borrowers'),a('pd','Common PD',.5,20,.5,3,'%'),a('lgd','Common LGD',10,100,5,50,'%')],challenge:'Keep PD and total exposure fixed. Can expected loss stay flat while concentration worsens?',formula:'HHI=Σ exposure_share²; effective name count=1/HHI\nIndependent loss SD=LGD×sqrt[PD(1−PD)×Σ EAD_i²]',simple:'Ten small loans do not offset a single loan that dominates the balance. The loss from that name is indivisible, even if its average PD is modest.',scope:'Equal PD and fixed LGD, independent default indicators for the displayed SD. Sector dependence is explained but not inferred from HHI. The largest-name label may not be the actual largest when its selected share is smaller than an equal remainder share.',compute(s){const w=s.share/100,h=w*w+(1-w)**2/s.others,pd=s.pd/100,lgd=s.lgd/100,sd=s.ead*lgd*Math.sqrt(pd*(1-pd)*h);return out([['HHI',h.toFixed(3)],['Effective equal names',(1/h).toFixed(1)],['Independent loss SD',m(sd)]],['Designated name','Other names total'],[s.ead*w,s.ead*(1-w)],[['EL',m(s.ead*pd*lgd),'Unchanged by allocation'],['Designated-name default loss',m(s.ead*w*lgd),'One indivisible event'],['Effective names',(1/h).toFixed(1),'Concentration summary']],`EL is ${m(s.ead*pd*lgd)} while concentration changes the loss dispersion. Shared sector exposure could add dependence beyond this independent-name calculation.`);}});
 add({id:'migration',name:'Ratings and migration',stage:'02 · Portfolio behaviour',title:'Credit can deteriorate before it defaults.',intro:'Move borrowers between stronger, weaker and default states using an editable transition mechanism.',chart:'Rating-state proportions through time (%)',inputs:[a('down','Strong → weak annual migration',0,30,1,10,'%'),a('default','Weak → default annual migration',0,30,1,8,'%'),a('cure','Weak → strong annual upgrade',0,30,1,10,'%'),a('years','Projection horizon',1,10,1,5,'years')],challenge:'Increase downgrades without changing the strong-grade direct PD. Why does long-run default still rise?',formula:'State distribution(t+1)=State distribution(t)×transition matrix',simple:'A downgrade is a warning about future credit quality. It can increase lifetime default risk and reduce market value before a default loss is realised.',scope:'Three-state time-homogeneous Markov model. Strong-grade direct default fixed at 1%, initial mix 80% strong / 20% weak, default absorbing. All row probabilities sum to one. No market-spread repricing, withdrawal of ratings or borrower-specific paths.',compute(s){const matrix=[[.99-s.down/100,s.down/100,.01],[s.cure/100,1-(s.cure+s.default)/100,s.default/100],[0,0,1]],r=M.migration(matrix,[.8,.2,0],s.years);return {stats:[['Final strong',p(r.at(-1)[0])],['Final weak',p(r.at(-1)[1])],['Cumulative default',p(r.at(-1)[2])]],series:['Strong','Weak','Default'].map((x,j)=>line(x,r.map((v,i)=>[i,100*v[j]]),['#285e46','#779db0','#b57e3e'][j])),xlabel:'Year',headers:['From / to','Strong','Weak','Default'],rows:matrix.map((v,i)=>[['Strong','Weak','Default'][i],...v.map(p)]),explanation:'Repeated migration accumulates default risk through intermediate weaker grades. A one-year transition matrix is an assumption about future behaviour, not a permanent law.'};}});
 add({id:'mortgage',name:'Mortgage collateral and LTV',stage:'02 · Portfolio behaviour',title:'Falling house prices change recovery, not just LTV.',intro:'Stress property values and selling costs, then compare collateral proceeds with the loan balance.',chart:'Collateral value and loan shortfall (£m)',inputs:[a('loan','Loan balance',1,200,1,80),a('property','Initial property value',1,300,1,100),a('fall','Property price decline',0,60,5,20,'%'),a('cost','Disposal costs',0,30,1,10,'%'),a('pd','Conditional one-year PD',.5,20,.5,2,'%')],challenge:'Can a loan that started below 100% LTV still suffer a collateral shortfall?',formula:'Net collateral=property×(1−price fall)×(1−cost)\nCollateral loss=max(loan−net collateral,0)',simple:'Collateral is a second source of repayment. Its market value can fall just when borrower distress rises, and disposal costs reduce what the lender receives.',scope:'Immediate collateral sale, no discount lag, prior liens, recourse recovery or guarantees. PD is separately selected, so joint PD/LGD stress must be considered explicitly. Collateral-derived loss severity is not a calibrated mortgage LGD or regulatory floor.',compute(s){const value=s.property*(1-s.fall/100),net=value*(1-s.cost/100),loss=Math.max(0,s.loan-net);return out([['Stressed LTV',p(s.loan/value)],['Collateral-only LGD',p(loss/s.loan)],['One-year EL',m(loss*s.pd/100)]],['Loan','Net collateral','Shortfall'],[s.loan,net,loss],[['Original LTV',p(s.loan/s.property),'Before price stress'],['Disposal costs',m(value-net),'Reduce recovery']],`After the house-price shock, net collateral is ${m(net)}. The collateral shortfall is ${m(loss)}, before any other recoveries or costs.`);}});
 add({id:'corporate',name:'Corporate, SME and project drivers',stage:'02 · Portfolio behaviour',title:'Debt service is paid from cash, not from a rating label.',intro:'Stress cash generation and floating debt cost, then map coverage into a deliberately simple risk indicator.',chart:'Cash available versus annual debt service (£m)',inputs:[a('cash','Cash available for debt service',1,100,1,20),a('debt','Debt principal',1,300,1,100),a('rate','Annual cash interest rate',0,20,.5,5,'%'),a('repay','Annual principal due',0,50,1,10),a('shock','Cash-flow decline',0,70,5,20,'%')],challenge:'Raise interest rates while holding debt principal fixed. What happens to repayment capacity?',formula:'DSCR=stressed cash/(interest+principal due)\nIllustrative PD=sigmoid(−3−2×(DSCR−1))',simple:'Leverage indicates indebtedness; coverage asks whether current cash can service it. Project and commercial-property lending also depend on occupancy, covenants, sponsors and refinancing at maturity.',scope:'One-period cash flow, all debt treated as floating or immediately repriced. Logistic PD mapping is invented for teaching and is not a fitted corporate or project-finance rating model. Zero debt service gives undefined coverage and no model PD. Financial institutions and sovereigns require different analysis.',compute(s){const cash=s.cash*(1-s.shock/100),service=s.debt*s.rate/100+s.repay,dscr=service?cash/service:null,pd=dscr===null?null:M.sigmoid(-3-2*(dscr-1));return out([['DSCR',dscr===null?'N/A · no service':dscr.toFixed(2)+'×'],['Cash after service',m(cash-service)],['Teaching PD',pd===null?'N/A':p(pd)]],['Available cash','Debt service','Residual'],[cash,service,cash-service],[['Interest',m(s.debt*s.rate/100),'Current repricing assumption'],['Principal due',m(s.repay),'Refinancing risk not simulated']],`Cash available is ${m(cash)} against ${m(service)} of annual service. The displayed PD is only an illustrative response curve; a real model needs representative outcomes and validation.`);}});
 add({id:'mitigation',name:'Guarantees and credit protection',stage:'02 · Portfolio behaviour',title:'Protection works only when the protector can pay.',intro:'Split default loss into uncovered exposure and covered loss subject to conditional guarantor failure.',chart:'Residual loss after an economic guarantee (£m)',inputs:[a('ead','Exposure',0,200,5,100),a('pd','Borrower PD',0,30,.5,3,'%'),a('lgd','Borrower LGD',0,100,5,50,'%'),a('cover','Loss covered',0,100,5,70,'%'),a('failure','Guarantor non-payment given borrower default',0,100,5,20,'%')],challenge:'Increase guarantor failure in the same stress that affects the borrower. How much protection remains?',formula:'EL=EAD×PD×LGD×[(1−coverage)+coverage×conditional non-payment]',simple:'A guarantee exchanges some borrower risk for reliance on the guarantor. A protector exposed to the same shock may be least able to pay exactly when protection is needed.',scope:'Economic expected-loss example, not regulatory PD substitution or double-default capital treatment. Conditional non-payment is directly assumed; no legal eligibility, maturity/currency mismatch, claim delay, premium or guarantee cap beyond the loss coverage fraction.',compute(s){const before=s.ead*s.pd*s.lgd/10000,after=before*(1-s.cover/100+s.cover*s.failure/10000);return out([['Unprotected EL',m(before)],['Protected EL',m(after)],['Expected benefit',m(before-after)]],['Before','After','Benefit'],[before,after,before-after],[['Covered loss share',s.cover+'%','Contract assumed enforceable'],['Conditional non-payment',s.failure+'%','Dependence captured directly']],`Expected protection reduces loss by ${m(before-after)}. At 100% conditional non-payment, the assumed guarantee offers no expected loss reduction.`);}});
 add({id:'pricing',name:'Risk-adjusted pricing',stage:'06 · Decisions and governance',title:'A higher loan spread is not automatically better business.',intro:'Build a one-year revenue bridge through funding cost, operating cost, expected loss and a capital hurdle.',chart:'One-year economic contribution (£m)',inputs:[a('ead','Exposure',10,300,10,100),a('spread','Customer margin over funding',0,12,.25,4,'%'),a('pd','One-year PD',0,20,.5,3,'%'),a('lgd','LGD',0,100,5,50,'%'),a('cost','Operating cost as exposure fraction',0,3,.1,1,'%'),a('capital','Allocated economic capital',1,50,1,10),a('hurdle','Capital hurdle',0,25,1,12,'%')],challenge:'Increase PD and raise the customer spread. Has risk-adjusted contribution necessarily improved?',formula:'Contribution=EAD×margin−EAD×PD×LGD−cost−capital×hurdle',simple:'Loan revenue must support expected losses and the resources needed to run and capitalise the business. A high coupon can merely compensate for a high risk of non-payment.',scope:'One-year static performing exposure. Margin is already net of funding; fixed EAD, no taxes, discounting or default-time lost interest. Economic capital is user allocated and not a computed regulatory requirement. RAROC uses pre-hurdle income divided by allocated capital.',compute(s){const revenue=s.ead*s.spread/100,loss=s.ead*s.pd*s.lgd/10000,cost=s.ead*s.cost/100,h=s.capital*s.hurdle/100,net=revenue-loss-cost;return out([['Pre-hurdle RAROC',p(net/s.capital)],['Economic contribution',m(net-h)],['Break-even margin',p((loss+cost+h)/s.ead)]],['Margin revenue','Expected loss','Operating cost','Capital cost','Contribution'],[revenue,-loss,-cost,-h,net-h],[['Expected loss',m(loss),'Cost of average defaults'],['Capital remuneration',m(h),'Cost, not capital principal']],`The economic contribution is ${m(net-h)} after the selected capital hurdle. A modelled positive contribution does not determine an approval decision by itself.`);}});
 add({id:'capital',name:'Accounting loss versus capital',stage:'06 · Decisions and governance',title:'Expected loss, provisions and capital answer different questions.',intro:'Contrast a selected accounting allowance with a user-assumed regulatory risk weight and capital ratio.',chart:'Distinct measures: allowance, RWA and capital (£m)',inputs:[a('ead','Exposure',10,300,10,100),a('allowance','Accounting ECL allowance',0,30,.5,3),a('rw','Illustrative risk weight',0,200,5,75,'%'),a('ratio','Capital ratio assumption',4,20,.5,10,'%')],challenge:'Hold ECL unchanged and raise the risk weight. Which quantity changes, and why?',formula:'Illustrative RWA=EAD×risk weight\nIllustrative capital=RWA×selected ratio',simple:'An allowance recognises expected credit losses in accounting. Capital supports resilience to losses and other risks under a separate framework. They are connected in reporting but cannot be substituted for one another.',scope:'No regulatory risk-weight table is implemented: risk weight and ratio are chosen assumptions. Omits prudential exposure adjustments, IRB formulae, eligibility, PD/LGD floors, maturity adjustments, output floor, provision shortfall/excess, buffers and tax effects. Links point to the applicable framework for those details.',sources:[refs.ifrs,refs.capital],compute(s){const rwa=s.ead*s.rw/100,k=rwa*s.ratio/100;return out([['Accounting allowance',m(s.allowance)],['Illustrative RWA',m(rwa)],['Capital at selected ratio',m(k)]],['Allowance','RWA','Capital'],[s.allowance,rwa,k],[['Standardised approach','Prescribed categories / risk weights','Must select jurisdiction and effective rules'],['IRB approach','Approved internal inputs and formulae','Different PD/LGD conventions from IFRS 9'],['Allowance','Accounting estimate','Not added to capital mechanically']],`At the selected assumptions, capital is ${m(k)} while the allowance is ${m(s.allowance)}. The chart separates measures, not a total funding requirement.`);}});
})();
